require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "applies symbol-keyed overrides as string keys and keeps an extra key as snapshot_item does" do
    entry = described_class.entry(id: 11, company_id: 3, version: 2, project_id: 5, user_id: 7,
                                  review_status: "approved", source: "cli", source_metadata: { "tool" => "codex" },
                                  updated_at: "2026-03-02T10:00:00+01:00", invoice_id: 7)

    expect(entry).to include("review_status" => "approved", "source" => "cli",
                             "source_metadata" => { "tool" => "codex" },
                             "updated_at" => "2026-03-02T10:00:00+01:00", "note" => "v2")
    # The builder merges overrides without refusing unknown keys, so specs that
    # send a key outside the contract on purpose still can.
    expect(entry["invoice_id"]).to eq(7)
    expect(entry.keys).not_to include(:review_status)
  end
end

require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "wraps an entry in an item with the contract's item_fields and the entry version as outbox_position" do
    entry = described_class.entry(id: 1, company_id: 2, version: 4, project_id: 3, user_id: 5)

    item = described_class.item(entry, generation: 1)
    positioned = described_class.item(entry, generation: 2, outbox_position: 9)

    expect(item.keys).to match_array(TimekeepingContract.load(:entry_snapshots).fetch("item_fields"))
    expect(item).to eq("generation" => 1, "outbox_position" => 4, "entry" => entry)
    expect(positioned).to eq("generation" => 2, "outbox_position" => 9, "entry" => entry)
  end
end

require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "wraps items in a batch with the contract's batch_fields and schema_version" do
    contract = TimekeepingContract.load(:entry_snapshots)
    first = described_class.item(described_class.entry(id: 1, company_id: 2, version: 1, project_id: 3, user_id: 4), generation: 1)
    second = described_class.item(described_class.entry(id: 1, company_id: 2, version: 2, project_id: 3, user_id: 4), generation: 1)

    batch = described_class.batch(first, second)

    expect(batch.keys).to match_array(contract.fetch("batch_fields"))
    expect(batch).to eq("schema_version" => contract.fetch("schema_version"), "snapshots" => [first, second])
    expect(described_class.batch).to eq("schema_version" => contract.fetch("schema_version"), "snapshots" => [])
  end
end

require "rails_helper"

RSpec.describe TimekeepingSnapshots do
  it "builds a batch that Timekeeping::SnapshotBatch accepts" do
    entry = described_class.entry(id: 11, company_id: 3, version: 2, project_id: 5, user_id: 7)

    parsed = Timekeeping::SnapshotBatch.parse(described_class.batch(described_class.item(entry, generation: 1)))

    expect(parsed).not_to be_nil
    item = parsed.sole
    expect([item.generation, item.outbox_position, item.entry_id, item.company_id, item.project_id]).to eq([1, 2, 11, 3, 5])
  end
end

